import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a static card label node for "Collection 3".
 * Applies a textured plane with a headline text overlay.
 */
export default function createNode(config, ctx) {
  const { textureLoader, fontAtlas, THREE } = ctx;

  // --- Container group ---
  const group = new THREE.Group();

  // --- Plane geometry (size derived from texture aspect ratio) ---
  const BASE_WIDTH = 1.8;
  const planeGeom = new THREE.PlaneGeometry(BASE_WIDTH, BASE_WIDTH * (320 / 512));
  const material = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
  });
  const planeMesh = new THREE.Mesh(planeGeom, material);
  group.add(planeMesh);

  // --- Load texture ---
  textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = 'srgb';
    const aspect = tex.image.width / tex.image.height;
    const height = BASE_WIDTH / aspect;
    planeGeom.dispose();
    const newGeom = new THREE.PlaneGeometry(BASE_WIDTH, height);
    planeMesh.geometry = newGeom;
    group.userData._planeGeom = newGeom;
    material.map = tex;
    material.needsUpdate = true;
  }).catch(() => {
    // fallback: keep placeholder
  });

  // --- Text content from config ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textObj = fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize || 39,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 300,
    });
    textObj.position.set(0, -0.55, 0.01);
    textObj.scale.setScalar(0.008);
    group.add(textObj);
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    planeGeom.dispose();
    if (group.userData._planeGeom) group.userData._planeGeom.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  group.userData._planeGeom = planeGeom;

  return group;
}
